  name: string;
  avatar: string;
  email: string;
}

export interface EmailData {
  from: Recipient;
  to: Recipient[];
  subject: string;
  body: string;
  attachments: Attachment[];
}

interface ComposeEmailCardProps {
  data: EmailData;
  onSend?: (data: EmailData) => void;
  onClose?: () => void;
}

type ActivePopover =
  | 'more'
  | 'emoji'
  | 'attach'
  | 'link'
  | 'ai'
  | 'schedule'
  | null;

const EMOJIS = [
  '😊',
  '👍',
  '🙌',
  '🔥',
  '💡',
  '✅',
  '🚀',
