import { useState, type FC, type ReactNode } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { useTheme } from "next-themes";

/* --- Types --- */

export interface ContinuousPaginationProps {
    totalPages?: number;
    defaultPage?: number;
}

/* --- Sub-Components --- */

interface PageButtonProps {
    children: ReactNode;
    onClick: () => void;
}

const PageButton: FC<PageButtonProps> = ({ children, onClick }) => {
    return (
        <motion.button
            onClick={onClick}
            className="h-10 w-10 sm:h-16 sm:w-16 rounded-lg sm:rounded-xl flex items-center justify-center text-[#706F78] dark:text-zinc-500 hover:text-[#65656c] dark:hover:text-zinc-300 border border-slate-500/20 dark:border-zinc-800 bg-white dark:bg-zinc-900 shadow-[0_4px_10px_rgba(0,0,0,0.12)]"
            whileHover={{
                scale: 1.08,
                y: -6,
                boxShadow: "0 6px 10px rgba(0,0,0,0.12)",
            }}
            whileTap={{ scale: 0.92 }}
            transition={{ type: "spring", stiffness: 400, damping: 20 }}
        >
            {children}
        </motion.button>
    );
};

/* --- Main Component --- */

export const ContinuousPagination: FC<ContinuousPaginationProps> = ({
    totalPages = 5,
    defaultPage = 1,
}) => {
    const [active, setActive] = useState<number>(defaultPage);
    const { resolvedTheme } = useTheme();

    const isDark = resolvedTheme === "dark";

    const paginate = (page: number) => {
        if (page < 1 || page > totalPages) return;
        setActive(page);
    };

    return (
        <div className="flex items-center justify-center gap-1.5 sm:gap-3 text-sm">
            {/* Prev */}
            <PageButton onClick={() => paginate(active - 1)}>
                <ChevronLeft className="w-5 h-5 sm:w-7 sm:h-7" />
            </PageButton>

            {/* Pages */}
            <div className="relative flex gap-1.5 sm:gap-3">
                {Array.from({ length: totalPages }).map((_, i) => {
                    const page = i + 1;
                    const isActive = page === active;

                    return (
                        <motion.button
                            key={page}
                            onClick={() => paginate(page)}
                            className={`relative z-10 h-10 w-10 sm:h-16 sm:w-16 rounded-lg sm:rounded-xl flex items-center justify-center text-sm font-medium transition-colors duration-300 border border-slate-500/20 dark:border-zinc-800 shadow-[0_4px_10px_rgba(0,0,0,0.12)]
                ${isActive
                                    ? "text-white"
                                    : "text-gray-500 dark:text-zinc-500 hover:text-gray-800 dark:hover:text-zinc-300 bg-white dark:bg-zinc-900"
                                }`}
                            whileHover={
                                !isActive
                                    ? {
                                        y: -6,
                                        boxShadow: isDark
                                            ? "0 10px 20px rgba(0,0,0,0.4)"
                                            : "0 6px 10px rgba(0,0,0,0.12)",
                                    }
                                    : {}
                            }
                            whileTap={{ scale: 0.92 }}
                            transition={{ type: "spring", stiffness: 260, damping: 18 }}
                        >
                            {/* Active background */}
                            <AnimatePresence>
                                {isActive && (
                                    <motion.div
                                        layoutId="active-bg"
                                        className="absolute inset-0 rounded-lg sm:rounded-xl overflow-hidden"
                                        initial={{ scale: 0.9, opacity: 0 }}
                                        animate={{ scale: 1, opacity: 1 }}
                                        exit={{ scale: 0.9, opacity: 0 }}
                                        transition={{ type: "spring", stiffness: 220, damping: 24, mass: 0.8 }}
                                    >
                                        <div
                                            className="absolute inset-0 rounded-lg sm:rounded-xl"
                                            style={{
                                                background: `linear-gradient(135deg, #2a2a2e 0%, #1a1a1c 50%, #0a0a0c 100%)`,
                                                border: `1px solid #3a3a3e`,
                                                boxShadow: `
                            0 8px 16px -4px rgba(0,0,0,0.7),
                            inset 0 1px 1px 0 rgba(255, 255, 255, 0.15)
                          `,
                                            }}
                                        />
                                        <motion.div
                                            className="absolute -inset-full bg-linear-to-tr from-transparent via-white/10 to-transparent skew-x-12"
                                            animate={{ x: ["-100%", "200%"] }}
                                            transition={{
                                                duration: 3,
                                                repeat: Infinity,
                                                repeatDelay: 5,
                                                ease: "easeInOut",
                                            }}
                                        />
                                        <span
                                            className="absolute inset-0 rounded-[inherit] pointer-events-none"
                                            style={{
                                                boxShadow: "inset 0 -4px 8px 0 rgba(0, 0, 0, 0.6)",
                                            }}
                                        />
                                    </motion.div>
                                )}
                            </AnimatePresence>

                            <span className="relative z-10 text-lg sm:text-xl font-semibold">{page}</span>
                        </motion.button>
                    );
                })}
            </div>

            {/* Next */}
            <PageButton onClick={() => paginate(active + 1)}>
                <ChevronRight className="w-5 h-5 sm:w-7 sm:h-7" />
            </PageButton>
        </div>
    );
};

"use client";

import { useState, useEffect, type FC } from "react";
import { motion, LayoutGroup } from "framer-motion";

/* ---------- Types ---------- */
interface TabItem {
    id: string;
    label: string;
}

interface ContinuousTabsProps {
    tabs?: TabItem[];
    defaultActiveId?: string;
    onChange?: (id: string) => void;
}

/* ---------- Defaults ---------- */
const DEFAULT_TABS: TabItem[] = [
    { id: "home", label: "Home" },
    { id: "interactions", label: "Interactions" },
    { id: "resources", label: "Resources" },
    { id: "docs", label: "Docs" },
];

export const ContinuousTabs: FC<ContinuousTabsProps> = ({
    tabs = DEFAULT_TABS,
    defaultActiveId = "home",
    onChange,
}) => {
    const [active, setActive] = useState<string>(defaultActiveId);
    const [isMounted, setIsMounted] = useState<boolean>(false);

    useEffect(() => {

        setIsMounted(true);
    }, []);

    const handleChange = (id: string) => {
        setActive(id);
        onChange?.(id);
    };

    if (!isMounted) return null;

    return (
        <LayoutGroup>
            <nav
                className="
          relative flex items-center gap-0.5 sm:gap-1 p-1 sm:p-1.5
            rounded-full
            border border-[#E5E5E9] dark:border-zinc-800
            bg-linear-to-b from-[#ffffff] to-[#e9e9f2]
            dark:from-zinc-900 dark:to-zinc-950
            shadow-[inset_0_-2px_4px_rgba(0,0,0,0.08),
                    inset_0_1px_0_rgba(255,255,255,0.9),
                    0_4px_12px_rgba(0,0,0,0.03)]
            dark:shadow-[inset_0_-2px_4px_rgba(0,0,0,0.5),
                    inset_0_1px_0_rgba(255,255,255,0.05),
                    0_10px_20px_rgba(0,0,0,0.4)]
            transition-all duration-300
          "
            >
                {tabs.map((tab) => {
                    const isActive = active === tab.id;

                    return (
                        <button
                            key={tab.id}
                            onClick={() => handleChange(tab.id)}
                            className="relative px-4 py-2 sm:px-6 sm:py-3 rounded-full outline-none"
                        >
                            {/* Active pill */}
                            {isActive && (
                                <motion.div
                                    layoutId="active-pill"
                                    transition={{
                                        type: "spring",
                                        stiffness: 380,
                                        damping: 30,
                                        mass: 0.9,
                                    }}
                                    className="
                      absolute inset-0 rounded-full
                      bg-[#252528] dark:bg-zinc-100
                      shadow-xs
                    "
                                />
                            )}

                            {/* Text */}
                            <motion.span
                                layout="position"
                                className={`relative z-10 text-sm sm:text-base font-semibold transition-colors duration-200
                    ${isActive
                                        ? "text-[#EDEDEC] dark:text-zinc-950"
                                        : "text-[#343437] dark:text-zinc-500 hover:text-[#62625D] dark:hover:text-zinc-300"
                                    }
                  `}
                            >
                                {tab.label}
                            </motion.span>
                        </button>
                    );
                })}
            </nav>
        </LayoutGroup>
    );
};

import {
  Boxes,
  CheckIcon,
  CopyIcon,
  Settings2,
} from 'lucide-react';
import { AnimatePresence, motion } from 'framer-motion';
import { type ReactNode, useState } from 'react';

interface SkillCardProps {
  title?: string;
  icon?: ReactNode;
  valueToCopy?: string;

  copiedText?: string;
  copyText?: string;

  showSettings?: boolean;
  loading?: boolean;

  onSettingsClick?: () => void;
}

export default function CopyConfirm({
  title = 'Clay Skill',
  icon = <Boxes size={16} />,
  valueToCopy = 'Clay Skill',

  copiedText = 'Copied',
  copyText = 'Copy',

  showSettings = true,
  loading = false,

  onSettingsClick = () => {},
}: SkillCardProps) {
  const [copied, setCopied] = useState(false);

  async function handleCopy() {
    await navigator.clipboard.writeText(valueToCopy);

    setCopied(true);

    setTimeout(() => {
      setCopied(false);
    }, 1800);
  }

  return (
    <div className="flex h-screen w-full items-center justify-center">
      <div className="flex items-center gap-2">
        <div className="flex gap-0.5 rounded-full">
          <div className="border-border/20 flex items-center gap-1.5 rounded-l-full border bg-zinc-100 p-3">
            <div className="text-zinc-500">{icon}</div>

            <span className="text-sm font-semibold text-zinc-800">
              {title}
            </span>
          </div>

          {showSettings && (
            <button
              onClick={onSettingsClick}
              className="flex items-center justify-center rounded-r-full bg-zinc-100 px-3 transition"
            >
              <Settings2 size={20} className="text-zinc-700" />
            </button>
          )}
        </div>

        <motion.button
          whileHover={{ scale: 1.02 }}
          whileTap={{ scale: 0.97 }}
          disabled={loading}
          animate={{
            backgroundColor: copied ? '#15803d' : '#000000', // green-500 : black
          }}
          onClick={handleCopy}
          className="relative flex  items-center justify-center gap-2 overflow-hidden rounded-full bg-[#0C3415] py-2 px-4 text-white"
        >
          <AnimatePresence mode="popLayout" initial={false}>
            <motion.div
              key={copied ? 'check' : 'copy'}
              initial={{ opacity: 0, scale: 0.25, filter: 'blur(4px)' }}
              animate={{ opacity: 1, scale: 1, filter: 'blur(0px)' }}
              exit={{ opacity: 0, scale: 0.25, filter: 'blur(4px)' }}
              transition={{
                type: 'spring',
                duration: 0.3,
                bounce: 0,
              }}
                          className='text-sm'
            >
              {copied ? (
                <CheckIcon className="stoke-2 size-4" />
              ) : (
                <CopyIcon className="stroke-2 size-4" />
              )}
            </motion.div>
          </AnimatePresence>
          <AnimatedText from={copyText} to={copiedText} isCopied={copied} />
        </motion.button>
      </div>
    </div>
  );
}

const AnimatedText = ({
  from,
  to,
  isCopied,
}: {
  from: string;
  to: string;
  isCopied: boolean;
}) => {
  const activeText = isCopied ? to : from;

  return (
    <div className="flex text-lg tracking-tight will-change-transform">
      <AnimatePresence mode="popLayout" initial={false}>
        {activeText.split('').map((char, index) => {
          const displayChar = char === ' ' ? '\u00A0' : char;

          return (
            <motion.span
              key={char + index}
              layout
              initial={{ opacity: 0, y: 5, scale: 0.7 }}
              animate={{
                opacity: 1,
                y: 0,
                scale: 1,
                transition: {
                  type: 'spring',
                  stiffness: 200,
                  damping: 20,
                  delay: 0.03 * index,
                },
              }}
              exit={{ opacity: 0, y: -5, scale: 0.7 }}
            >
              {displayChar}
            </motion.span>
          );
        })}
      </AnimatePresence>
    </div>
  );
};

