'use client';

import {
  useState,
  useRef,
  useEffect,
  type FC,
  type ChangeEvent,
  type KeyboardEvent,
  type MouseEvent,
} from 'react';
import { motion, AnimatePresence } from 'motion/react';

import { BiSolidPencil } from 'react-icons/bi';
import { Check } from 'lucide-react';
import { cn } from '@/lib/utils';

interface EditableChipProps {
  defaultLabel?: string;
  showThemeToggle?: boolean;
  onChange?: (value: string) => void;
}

export const EditableChip: FC<EditableChipProps> = ({
  defaultLabel = 'Watchlist',
  onChange,
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [label, setLabel] = useState<string>(defaultLabel);

  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isEditing && inputRef.current) {
      requestAnimationFrame(() => {
        inputRef.current?.focus();
        inputRef.current?.select();
      });
    }
  }, [isEditing]);

  const handleSave = (e: MouseEvent | KeyboardEvent) => {
    e.stopPropagation();
    const finalValue = label.trim() === '' ? 'Untitled' : label;
    setLabel(finalValue);
    setIsEditing(false);
    onChange?.(finalValue);
  };

  const handleEdit = () => {
    setIsEditing(true);
  };

  return (
      <motion.div layout>
        <div
          className={cn(
            `relative flex cursor-pointer items-center justify-center gap-2 overflow-hidden rounded-full border border-zinc-200 py-1 pr-1 transition-all duration-300 ease-in-out select-none dark:border-zinc-700 dark:bg-zinc-900`,
            isEditing && 'gap-8 ring-2 ring-black dark:ring-white',
          )}
        >
          <motion.input
            layout="position"
            key="input"
            ref={inputRef}
            type="text"
            value={label}
            readOnly={!isEditing}
            onChange={(e: ChangeEvent<HTMLInputElement>) =>
              setLabel(e.target.value)
            }
            onKeyDown={(e: KeyboardEvent<HTMLInputElement>) =>
              e.key === 'Enter' && handleSave(e)
            }

            onClick={(e: MouseEvent) => e.stopPropagation()}
            className="ml-4 w-32 border-none bg-transparent text-lg font-medium text-[#262626] capitalize outline-none selection:bg-[#B6B6B6] dark:text-zinc-100 dark:selection:bg-zinc-700"
          />

          <AnimatePresence mode="popLayout">
            {isEditing ? (
              <motion.button
                key="done"
                initial={{ opacity: 0, filter: 'blur(4px)', scale: 0 }}
                animate={{ opacity: 1, filter: 'blur(0px)', scale: 1 }}
                exit={{ opacity: 0, filter: 'blur(4px)', scale: 0 }}
                layout="position"
                onClick={handleSave}
                transition={{
                  type: 'spring',
                  bounce: 0,
                  duration: 0.4,
                }}
                className="rounded-full bg-black p-1 text-white transition-colors dark:bg-zinc-100 dark:text-zinc-950"
              >
                <Check size={26} />
              </motion.button>
            ) : (
              <motion.button
                key="edit"
                initial={{ opacity: 0, filter: 'blur(4px)', scale: 0 }}
                animate={{ opacity: 1, filter: 'blur(0px)', scale: 1 }}
                exit={{ opacity: 0, filter: 'blur(4px)', scale: 0 }}
                layout="position"
                onClick={handleEdit}
                transition={{
                  type: 'spring',
                  bounce: 0,
                  duration: 0.4,
                }}
                className="rounded-full bg-[#F0EFF6] p-1 text-[#696871] transition-colors dark:bg-zinc-800 dark:text-zinc-400 hover:dark:bg-zinc-700"
              >
                <BiSolidPencil size={26} />
              </motion.button>
            )}
          </AnimatePresence>
        </div>
      </motion.div>
  );
};

'use client';

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'motion/react';

export interface InterestItem {
  id: string;
  label: string;
  emoji: string;
}

interface Particle {
  id: string;
  emoji: string;
  xOffset: number;
  rotate: number;
}

interface Props {
  interests: InterestItem[];
  onChange?: (selectedIds: string[]) => void;
}

export const EmojiSpreeChips: React.FC<Props> = ({ interests, onChange }) => {
  const [selected, setSelected] = useState<string[]>([]);
  const [particles, setParticles] = useState<Particle[]>([]);
  const [isPanning, setIsPanning] = useState(false);
  const containerRef = React.useRef<HTMLDivElement>(null);

  const spawnParticles = (emoji: string) => {
    const newParticles: Particle[] = Array.from({ length: 3 }).map(() => ({
      id: crypto.randomUUID(),
      emoji,
      xOffset: (Math.random() - 0.5) * 180,
      rotate: (Math.random() - 0.5) * 40,
    }));

    setParticles(newParticles);

    setTimeout(() => {
      setParticles([]);
    }, 1600);
  };

  const toggleInterest = (id: string, emoji: string) => {
    setSelected((prev) => {
      const exists = prev.includes(id);
      const updated = exists ? prev.filter((i) => i !== id) : [...prev, id];

      onChange?.(updated);

      if (!exists) spawnParticles(emoji);

      return updated;
    });
  };

  const rows = React.useMemo(() => {
    const result: InterestItem[][] = [[], [], []];
    interests.forEach((item, index) => {
      result[index % 3].push(item);
    });
    return result;
  }, [interests]);

  return (
    <div className="relative isolate flex min-h-[500px] w-full max-w-4xl flex-col items-center overflow-hidden py-10 sm:min-h-[600px]">
      <h2 className="mb-6 w-full self-start px-6 text-2xl font-bold sm:mb-8 sm:text-3xl">
        Interests
      </h2>

      {/* Chips */}
      <motion.div
        ref={containerRef}
        className={`relative z-20 w-full cursor-grab overflow-hidden mask-r-from-90% mask-l-from-90% px-6 active:cursor-grabbing ${
          isPanning ? 'touch-none' : 'touch-pan-y'
        }`}
      >
        <motion.div
          drag="x"
          dragConstraints={containerRef}
          onPanStart={() => setIsPanning(true)}
          onPanEnd={() => setIsPanning(false)}
          className="flex w-max flex-col gap-4 pr-12 sm:gap-5"
        >
          {rows.map((row, rowIndex) => (
            <div key={rowIndex} className="flex w-max gap-4 sm:gap-5">
              {row.map((item) => {
                const isSelected = selected.includes(item.id);

                return (
                  <motion.button
                    key={item.id}
                    whileTap={{ scale: 0.95 }}
                    transition={{ type: 'spring', stiffness: 260, damping: 18 }}
                    onClick={() => toggleInterest(item.id, item.emoji)}
                    className={`flex w-max items-center gap-2 rounded-full border px-4 py-1.5 text-base font-semibold whitespace-nowrap sm:gap-3 sm:px-5 sm:py-2 sm:text-lg ${
                      isSelected
                        ? 'border-neutral-300 bg-white dark:border-neutral-600 dark:bg-neutral-800'
                        : 'border-neutral-200 bg-neutral-100 dark:border-neutral-800 dark:bg-neutral-900'
                    }`}
                  >
                    <span>{item.emoji}</span>
                    <span>{item.label}</span>
                  </motion.button>
                );
              })}
            </div>
          ))}
        </motion.div>
      </motion.div>

      {/* PARTICLES */}
      <div className="pointer-events-none absolute inset-0">
        <AnimatePresence>
          {particles.map((p, index) => (
            <FloatingEmoji
              key={p.id}
              emoji={p.emoji}
              delay={index * 0.08}
              xOffset={p.xOffset}
              rotate={p.rotate}
            />
          ))}
        </AnimatePresence>
      </div>

      {/* Selected Pill */}
      <div className="absolute bottom-8 left-1/2 z-20 -translate-x-1/2 sm:bottom-12">
        <AnimatePresence>
          {selected.length > 0 && (
            <motion.div
              initial={{ opacity: 0, y: 50, scale: 0.9 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 40 }}
              transition={{
                type: 'spring',
                stiffness: 200,
                damping: 20,
              }}
              className="relative rounded-full border bg-white px-6 py-2.5 text-lg font-bold shadow-lg sm:px-10 sm:py-4 sm:text-xl dark:bg-neutral-900"
            >
              {selected.length} Interests
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

/* Floating Emoji Component */
const FloatingEmoji = ({
  emoji,
  delay,
  xOffset,
  rotate,
}: {
  emoji: string;
  delay: number;
  xOffset: number;
  rotate: number;
}) => {
  const [phase, setPhase] = useState<'up' | 'down'>('up');
  const isMobile = React.useSyncExternalStore(
    (callback) => {
      window.addEventListener('resize', callback);
      return () => window.removeEventListener('resize', callback);
    },
    () => window.innerWidth < 640,
    () => false
  );

  return (
    <motion.div
      initial={{ y: 0, x: 0, opacity: 0, scale: 0.6, rotate: 0 }}
      animate={{
        y: [0, isMobile ? -180 : -260, isMobile ? -180 : -260, 30],
        x: [
          0,
          xOffset * (isMobile ? 0.6 : 1),
          xOffset * (isMobile ? 0.5 : 0.8),
        ],
        opacity: [0, 1, 1, 0],
        scale: [0.6, isMobile ? 2 : 3, isMobile ? 2 : 3, 0.6],
        rotate: [0, rotate, rotate * 0.5],
      }}
      transition={{
        duration: 1,
        ease: 'easeInOut',
        delay,
      }}
      onUpdate={(latest) => {
        if (typeof latest.y === 'number') {
          const threshold = isMobile ? -90 : -130;
          if (latest.y < threshold) {
            setPhase('up');
          } else {
            setPhase('down');
          }
        }
      }}
      className={`absolute bottom-20 left-1/2 -translate-x-1/2 text-4xl sm:text-6xl ${
        phase === 'up' ? 'z-30' : 'z-10'
      }`}
    >
      {emoji}
    </motion.div>
  );
};

"use client";

import { useState, useEffect, type FC, type ReactNode } from "react";
import { motion, AnimatePresence } from "motion/react";

 interface TabItem {
  id: string;
  icon: ReactNode;
  label: string;
  activeColor: string;
}

 interface DiscreteTabsProps {
  tabs: TabItem[];
  onTabChange?: (tabId: string) => void;
  defaultTab?: string;
}

export const DiscreteTabs: FC<DiscreteTabsProps> = ({ tabs, onTabChange, defaultTab }) => {
  const [activeTab, setActiveTab] = useState<string>(defaultTab || tabs[0]?.id);
  const [shine, setShine] = useState<boolean>(false);

  const handleTabClick = (tabId: string) => {
    setActiveTab(tabId);
    if (onTabChange) onTabChange(tabId);
  };

  useEffect(() => {
    const timer = setTimeout(() => setShine(true), 600);
    return () => {
      clearTimeout(timer);
      setShine(false);
    };
  }, [activeTab]);

  return (
<div className="flex items-center justify-center gap-2 rounded-full py-6 overflow-hidden w-fit mx-auto">
      {tabs.map((tab) => {
        const isActive = tab.id === activeTab;
        return (
          <button
            key={tab.id}
            onClick={() => handleTabClick(tab.id)}
            className="relative focus:outline-none"
          >
            <motion.div
              layout="position"
              transition={{ type: "spring", stiffness: 210, damping: 18, mass: 1 }}
              className={`relative flex h-16 ${isActive ? "w-40" : "w-full"} items-center justify-center`}
            >
              {isActive && (
                <motion.div
                  layoutId="activeBg"
                  className="absolute inset-0 rounded-full bg-white dark:bg-zinc-800 shadow-md"
                  transition={{ type: "spring", stiffness: 220, damping: 26 }}
                />
              )}
              <div className="relative z-10 flex items-center gap-1 pr-3 cursor-pointer">
                <motion.div
                  animate={{ scale: isActive ? 1.08 : 1 }}
                  className={`flex h-14 w-14 items-center justify-center rounded-full ${
                    isActive ? tab.activeColor : "bg-white dark:bg-zinc-900 text-gray-800"
                  }`}
                >
                  {tab.icon}
                </motion.div>
                <motion.span
                  animate={{ width: isActive ? "auto" : 0, opacity: isActive ? 1 : 0 }}
                  className={`relative overflow-hidden whitespace-nowrap text-xl font-semibold ${
                    isActive ? tab.activeColor : "text-black dark:text-white"
                  }`}
                >
                  {tab.label}
                  <AnimatePresence>
                    {isActive && shine && (
                      <motion.span
                        initial={{ left: "-120%" }}
                        animate={{ left: "120%" }}
                        className="absolute top-0 bottom-0 w-16 bg-gradient-to-r from-transparent via-white/60 to-transparent"
                      />
                    )}
                  </AnimatePresence>
                </motion.span>
              </div>
            </motion.div>
          </button>
        );
      })}
    </div>
  );
};

"use client";

import React, { useState, useRef, useEffect } from "react";
import { motion, AnimatePresence, MotionConfig } from "motion/react";
import { X } from "lucide-react";
import { FaPen } from "react-icons/fa6";
import { MdDraw } from "react-icons/md";
import { FaCheckCircle, FaRedo } from "react-icons/fa";
import { useTheme } from "next-themes";
import useMeasure from "react-use-measure";
import { cn } from "@/lib/utils";

interface DrawSignatureComponentProps {
  startLabel?: string;
  finishLabel?: string;
  doneLabel?: string;
  defaultStep?: "idle" | "drawing" | "done";
  onFinish?: (canvas: HTMLCanvasElement | null) => void;
  onClear?: () => void;
  onStepChange?: (step: "idle" | "drawing" | "done") => void;
}

export const DrawSignatureComponent: React.FC<DrawSignatureComponentProps> = ({
  startLabel = "Start Signing",
  finishLabel = "Finish Signing",
  doneLabel = "Signing Done",
  defaultStep = "idle",
  onFinish,
  onClear,
  onStepChange,
}) => {
  const [step, setStep] = useState<"idle" | "drawing" | "done">(defaultStep);
  const [ref, bounds] = useMeasure({ offsetSize: true });
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [savedSignature, setSavedSignature] = useState<string | null>(null);
  const { resolvedTheme } = useTheme();
  const [mounted, setMounted] = useState(false);

  useEffect(() => {

    setMounted(true);
  }, []);

  useEffect(() => {
    onStepChange?.(step);
  }, [step, onStepChange]);

  useEffect(() => {
    if (step === "drawing" && canvasRef.current) {
      const canvas = canvasRef.current;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;

      ctx.strokeStyle = resolvedTheme === "dark" ? "#ffffff" : "#000000";
      ctx.lineWidth = 3;
      ctx.lineCap = "round";
      ctx.lineJoin = "round";

      if (savedSignature) {
        const img = new Image();
        img.src = savedSignature;
        img.onload = () => {
          ctx.clearRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(img, 0, 0);
        };
      }
    }
  }, [step, resolvedTheme, savedSignature]);

  if (!mounted) return null;

  const startDrawing = (e: React.MouseEvent | React.TouchEvent) => {
    setIsDrawing(true);
    draw(e);
  };

  const stopDrawing = () => {
    setIsDrawing(false);
    const ctx = canvasRef.current?.getContext("2d");
    ctx?.beginPath();
  };

  const draw = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDrawing || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const rect = canvas.getBoundingClientRect();
    const x = ("touches" in e ? e.touches[0].clientX : e.clientX) - rect.left;
    const y = ("touches" in e ? e.touches[0].clientY : e.clientY) - rect.top;

    ctx.lineTo(x, y);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, y);
  };

  const clearCanvas = () => {
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext("2d");
    if (canvas && ctx) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
    }

    setSavedSignature(null);
    onClear?.();
  };

  const finishSigning = () => {
    if (canvasRef.current) {
      const dataUrl = canvasRef.current.toDataURL();
      setSavedSignature(dataUrl);
    }

    setStep("done");
    onFinish?.(canvasRef.current);
  };

  const penColor = resolvedTheme === "dark" ? "white" : "black";

  return (
    <MotionConfig
      transition={{
        type: "spring",
        bounce: 0.15,
        duration: 0.7,
      }}
    >
      <motion.div
        animate={{
          width: bounds.width > 0 ? bounds.width : "auto",
          height: bounds.height > 0 ? bounds.height : "auto",
        }}
        className={cn(
          "relative z-10 flex items-center justify-center overflow-hidden border-4 border-dashed border-transparent transition-colors duration-400 ease-out",
          step === "drawing" &&
            "border-4 border-dashed border-neutral-300 dark:border-neutral-700"
        )}
        style={{
          borderRadius: 32,
        }}
      >
        <div ref={ref} className="i flex shrink-0 p-1">
          <AnimatePresence mode="popLayout" initial={false}>
            {step === "idle" && (
              <motion.button
                key="start"
                // exit={{ opacity: 0, transition: { duration: 0 } }}
                layoutId="container-button"
                onClick={() => setStep("drawing")}
                className="flex items-center gap-2 rounded-full bg-neutral-100 px-8 py-5 text-lg font-bold text-neutral-900 hover:bg-neutral-200 dark:bg-neutral-800 dark:text-neutral-100 dark:hover:bg-neutral-700"
              >
                <motion.div layoutId="container-button-icon">
                  <MdDraw size={24} />
                </motion.div>
                <motion.span layoutId="container-button-text">
                  {startLabel}
                </motion.span>
              </motion.button>
            )}

            {step === "drawing" && (
              <motion.div
                key="pad"
                exit={{
                  opacity: 0,
                  y: "-30%",
                  x: "-10%",
                }}
                className="w-[320px] max-w-[320px] rounded-[34px] bg-white p-6 pb-4 will-change-transform dark:bg-neutral-900"
              >
                <div className="mb-6 flex items-center justify-between">
                  <button
                    onClick={clearCanvas}
                    className="text-neutral-400 hover:text-neutral-600 dark:text-neutral-500 dark:hover:text-neutral-300"
                  >
                    <FaRedo size={22} />
                  </button>

                  <span className="text-lg font-bold text-neutral-500 dark:text-neutral-400">
                    Sign
                  </span>

                  <button
                    onClick={() => setStep("idle")}
                    className="flex h-7 w-7 items-center justify-center rounded-full bg-neutral-400 text-white hover:bg-neutral-500 dark:bg-neutral-700 dark:hover:bg-neutral-600"
                  >
                    <X size={20} />
                  </button>
                </div>

                <canvas
                  ref={canvasRef}
                  width={290}
                  height={200}
                  onMouseDown={startDrawing}
                  onMouseMove={draw}
                  onMouseUp={stopDrawing}
                  onMouseLeave={stopDrawing}
                  onTouchStart={startDrawing}
                  onTouchMove={draw}
                  onTouchEnd={stopDrawing}
                  className="h-[200px] w-full touch-none"
                  style={{
                    cursor: `url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="34" height="34" viewBox="0 0 24 24" fill="${penColor}" stroke="${
                      resolvedTheme === "dark" ? "black" : "white"
                    }" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/><path d="m15 5 4 4"/></svg>') 0 22, auto`,
                  }}
                />

                <motion.button
                  layoutId="container-button"
                  exit={{ opacity: 0, transition: { duration: 0 } }}
                  whileTap={{ scale: 0.97 }}
                  onClick={finishSigning}
                  className="mt-4 flex w-full items-center justify-center gap-2 rounded-full bg-neutral-100 px-6 py-4 text-lg font-bold text-neutral-900 hover:bg-neutral-200 dark:bg-neutral-800 dark:text-neutral-100 dark:hover:bg-neutral-700"
                >
                  <motion.div layoutId="container-button-icon">
                    <MdDraw size={28} />
                  </motion.div>
                  <motion.span layoutId="container-button-text">
                    {finishLabel}
                  </motion.span>
                </motion.button>
              </motion.div>
            )}

            {step === "done" && (
              <motion.div
                key="done"
                exit={{ opacity: 0, transition: { duration: 0 } }}
                className="flex items-center gap-3"
                layoutId="container-button"
              >
                <motion.div className="flex items-center gap-2 rounded-full bg-neutral-900 px-6 py-4 text-lg font-bold text-white dark:bg-neutral-100 dark:text-neutral-900">
                  <motion.div layoutId="container-button-icon">
                    <FaCheckCircle size={24} />
                  </motion.div>
                  <motion.span layoutId="container-button-text">
                    {doneLabel}
                  </motion.span>
                </motion.div>

                <motion.button
                  // initial={{ scale: 0.5, opacity: 0 }}
                  // animate={{ scale: 1, opacity: 1 }}
                  onClick={() => setStep("drawing")}
                  className="rounded-full bg-neutral-100 p-4 text-neutral-900 hover:bg-neutral-200 dark:bg-neutral-800 dark:text-neutral-100 dark:hover:bg-neutral-700"
                >
                  <FaPen size={22} />
                </motion.button>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </motion.div>
    </MotionConfig>
  );
};

import React, { useState } from 'react';
import { motion, AnimatePresence, LayoutGroup } from 'motion/react';
import { Minus, Plus, X, ChevronUp, ChevronDown } from 'lucide-react';
import { FaBell, FaCheck } from 'react-icons/fa6';
import { MdEmail } from 'react-icons/md';
import { BiSolidPencil } from 'react-icons/bi';

export type ReminderType = 'Notification' | 'Email';
export type TimeUnit = 'minutes' | 'hours' | 'days';

export interface Reminder {
  id: string;
  type: ReminderType;
  value: number;
  unit: TimeUnit;
}

const NumberRoller = ({ value }: { value: number }) => {
  const [prevValue, setPrevValue] = React.useState(value);
  const direction = value >= prevValue ? 1 : -1;

  React.useEffect(() => {
    setPrevValue(value);
  }, [value]);

  const variants = {
    initial: (d: number) => ({
      y: d * 5,
      opacity: 0,
      scale: 0,
      filter: 'blur(2px)',
    }),
    animate: { y: 0, opacity: 1, scale: 1, filter: 'blur(0px)' },
    exit: (d: number) => ({
      y: d * -5,
      opacity: 0,
      scale: 0,
      filter: 'blur(2px)',
    }),
  };

  const strValue = value.toString().padStart(2, '0');

  return (
    <div className="flex items-center justify-center overflow-hidden">
      {strValue.split('').map((char, i) => (
        <div key={i} className="relative flex items-center justify-center">
          <span className="invisible text-lg font-bold tabular-nums">
            {char}
          </span>
          <AnimatePresence custom={direction} initial={false}>
            <motion.span
              key={char}
              custom={direction}
              variants={variants}
              initial="initial"
              animate="animate"
              exit="exit"
              transition={{ type: 'spring', bounce: 0, duration: 0.3 }}
              className="absolute text-lg font-bold text-neutral-900 tabular-nums dark:text-white"
            >
              {char}
            </motion.span>
          </AnimatePresence>
        </div>
      ))}
    </div>
  );
};

const AnimatedWord = ({ word }: { word: string }) => {
  return (
    <div className="relative flex items-center overflow-hidden">
      <AnimatePresence mode="popLayout" initial={false}>
        {word.split('').map((char, i) => (
          <motion.span
            key={`${char}-${i}`}
            initial={{ y: 5, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: -5, opacity: 0 }}
            transition={{
              type: 'spring',
              bounce: 0,
              duration: 0.3,
              delay: i * 0.0175,
            }}
            className="inline-block font-semibold text-neutral-800 dark:text-neutral-200"
          >
            {i === 0 ? char.toUpperCase() : char}
          </motion.span>
        ))}
      </AnimatePresence>
    </div>
  );
};

interface EventRemindersProps {
  title: string;
  date: string;
  initialReminders?: Reminder[];
  onUpdate?: (reminders: Reminder[]) => void;
}

export const EventReminders: React.FC<EventRemindersProps> = ({
  title,
  date: initialDate,
  initialReminders = [],
}) => {
  const [reminders, setReminders] = useState<Reminder[]>(initialReminders);
  const [date, setDate] = useState(initialDate);
  const [isEditingDate, setIsEditingDate] = useState(false);

  const basePill =
    'border-[1.6px] rounded-full transition-colors bg-white border-neutral-200 dark:bg-neutral-900 dark:border-neutral-800';

  const softBtn =
    'p-2 rounded-full transition-colors bg-neutral-100 text-neutral-500 hover:text-neutral-900 dark:bg-neutral-800 dark:text-neutral-400 dark:hover:text-white';

  const addReminder = () => {
    setReminders([
      ...reminders,
      {
        id: crypto.randomUUID(),
        type: 'Notification',
        value: 5,
        unit: 'minutes',
      },
    ]);
  };

  const removeReminder = (id: string) =>
    setReminders(reminders.filter((r) => r.id !== id));

  const updateReminder = (id: string, updates: Partial<Reminder>) =>
    setReminders(
      reminders.map((r) => (r.id === id ? { ...r, ...updates } : r)),
    );

  const toggleUnit = (id: string, current: TimeUnit) => {
    const units: TimeUnit[] = ['minutes', 'hours', 'days'];
    const next = units[(units.indexOf(current) + 1) % units.length];
    updateReminder(id, { unit: next });
  };

  return (
    <div className="flex min-h-full flex-col items-center justify-center bg-transparent p-4 antialiased">
      <motion.div
        layout
        transition={{
          type: 'spring',
          bounce: 0.2,
          duration: 0.5,
        }}
        className="w-full max-w-100 rounded-[32px] border-2 border-neutral-200 bg-white p-6 shadow-lg transition-colors dark:border-neutral-800 dark:bg-neutral-900"
      >
        {/* Header */}
        <div className="mb-6 flex items-start justify-between gap-3">
          <div className="min-w-0 flex-1">
            <h2 className="leading-tight text-lg font-bold text-neutral-900 sm:text-xl dark:text-white">
              {title}
            </h2>

            <AnimatePresence mode="wait">
              {isEditingDate ? (
                <motion.input
                  key="edit-date"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  onKeyDown={(e) =>
                    e.key === 'Enter' && setIsEditingDate(false)
                  }
                  autoFocus
                  className="mt-2 w-full rounded border-b-2 border-neutral-300 bg-neutral-100 px-2 py-1 font-semibold text-neutral-600 outline-none dark:border-neutral-700 dark:bg-neutral-800 dark:text-neutral-300"
                />
              ) : (
                <motion.p
                  key="view-date"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  className="mt-2 font-semibold text-neutral-600 dark:text-neutral-400"
                >
                  {date}
                </motion.p>
              )}
            </AnimatePresence>
          </div>

          <button
            onClick={() => setIsEditingDate(!isEditingDate)}
            className="rounded-lg border-2 border-neutral-200 bg-white p-2 text-neutral-600 transition-colors hover:bg-neutral-100 dark:border-neutral-700 dark:bg-neutral-800 dark:text-neutral-400 dark:hover:bg-neutral-700"
          >
            {isEditingDate ? (
              <FaCheck size={20} />
            ) : (
              <BiSolidPencil size={20} />
            )}
          </button>
        </div>

        {/* List */}
        <div className="border-t border-dashed border-neutral-200 pt-2 dark:border-neutral-800">
          <LayoutGroup>
            <AnimatePresence mode="popLayout">
              {reminders.map((reminder) => (
                <motion.div
                  key={reminder.id}
                  layout
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -10 }}
                  transition={{
                    type: 'spring',
                    bounce: 0.2,
                    duration: 0.5,
                  }}
                  className="space-y-3 border-b border-dashed border-neutral-200 py-4 dark:border-neutral-800"
                >
                  {/* Type */}
                  <motion.div
                    layout
                    onClick={() =>
                      updateReminder(reminder.id, {
                        type:
                          reminder.type === 'Notification'
                            ? 'Email'
                            : 'Notification',
                      })
                    }
                    className={`${basePill} flex cursor-pointer items-center justify-between px-4 py-2`}
                  >
                    <div className="flex items-center gap-3">
                      <AnimatePresence mode="popLayout" initial={false}>
                        <motion.div
                          key={reminder.type}
                          initial={{ y: 5, opacity: 0, filter: 'blur(4px)' }}
                          animate={{ y: 0, opacity: 1, filter: 'blur(0px)' }}
                          exit={{ y: -5, opacity: 0, filter: 'blur(4px)' }}
                          transition={{
                            type: 'spring',
                            bounce: 0,
                            duration: 0.5,
                          }}
                        >
                          {reminder.type === 'Notification' ? (
                            <FaBell size={18} className="text-neutral-400" />
                          ) : (
                            <MdEmail size={18} className="text-neutral-400" />
                          )}
                        </motion.div>
                      </AnimatePresence>
                      <AnimatedWord word={reminder.type} />
                    </div>
                    <div className="flex flex-col -space-y-1 text-neutral-400">
                      <ChevronUp size={14} strokeWidth={3} />
                      <ChevronDown size={14} strokeWidth={3} />
                    </div>
                  </motion.div>

                  {/* Value + Unit */}
                  <div className="flex flex-wrap sm:flex-nowrap items-center gap-2 relative">
                    <div
                      className={`${basePill} flex flex-1 min-w-[120px] items-center justify-between px-2 py-1`}
                    >
                      <button
                        onClick={() =>
                          updateReminder(reminder.id, {
                            value: Math.max(1, reminder.value - 1),
                          })
                        }
                        className={softBtn}
                      >
                        <Minus size={16} />
                      </button>

                      <NumberRoller value={reminder.value} />

                      <button
                        onClick={() =>
                          updateReminder(reminder.id, {
                            value: reminder.value + 1,
                          })
                        }
                        className={softBtn}
                      >
                        <Plus size={16} />
                      </button>
                    </div>

                    <motion.div
                      layout
                      onClick={() => toggleUnit(reminder.id, reminder.unit)}
                      className={`${basePill} flex flex-[1.4] min-w-[120px] cursor-pointer items-center justify-between px-4 py-2`}
                    >
                      <AnimatedWord word={reminder.unit} />
                      <div className="flex flex-col -space-y-1 text-neutral-400">
                        <ChevronUp size={14} strokeWidth={3} />
                        <ChevronDown size={14} strokeWidth={3} />
                      </div>
                    </motion.div>

                    <button
                      onClick={() => removeReminder(reminder.id)}
                      className="shrink-0 rounded-full border border-neutral-200 p-2.5 sm:p-3 text-neutral-500 transition-colors hover:bg-neutral-100 hover:text-red-500 dark:border-neutral-700 dark:text-neutral-400 dark:hover:bg-neutral-800"
                    >
                      <X size={18} strokeWidth={2.5} />
                    </button>
                  </div>
                </motion.div>
              ))}
            </AnimatePresence>
          </LayoutGroup>
        </div>

        {/* Add Button */}
        <motion.button
          onClick={addReminder}
          className="mt-6 flex w-full items-center justify-center gap-2 rounded-2xl bg-neutral-100 py-3 font-semibold text-neutral-800 transition-colors hover:bg-neutral-200 dark:bg-neutral-800 dark:text-neutral-200 dark:hover:bg-neutral-700"
        >
          <Plus size={18} strokeWidth={2.5} />
          Add Reminder
        </motion.button>
      </motion.div>
    </div>
  );
};

